const KEY = 'matematica-algebrista-44-v1';
const $ = id => document.getElementById(id);
let activeWeek = null;
const stages = ['read','video','practice','correction','review'];
const stageLabels = {read:'Leitura',video:'Videoaula',practice:'Exercícios',correction:'Correção',review:'Revisão'};
function storageGet(key,fallback=''){try{const v=localStorage.getItem(key);return v===null?fallback:v}catch(e){return fallback}}
function storageSet(key,value){try{localStorage.setItem(key,value);return true}catch(e){return false}}
function readProgress(){try{const v=JSON.parse(storageGet(KEY+'-progress','{}'));return v&&typeof v==='object'?v:{}}catch(e){return {}}}
let progress=readProgress();
function getState(week){return progress[week]||{read:false,video:false,practice:false,correction:false,review:false}}
function completed(s){return stages.every(k=>!!s[k])}
function render(){
 const done=curriculum.filter(w=>completed(getState(w.week))).length;
 $('overallPercent').textContent=Math.round(done/44*100)+'%';$('overallBar').style.width=(done/44*100)+'%';$('doneCount').textContent=done;$('totalCount').textContent='44 semanas';
 const filter=$('weekFilter').value;
 $('weeks').innerHTML=curriculum.map(w=>{const s=getState(w.week),count=stages.filter(k=>s[k]).length,finished=completed(s);if(filter==='done'&&!finished)return '';if(filter==='pending'&&finished)return '';return `<article class="week-card"><button class="week-head" type="button" aria-expanded="false"><span><span class="week-title">Semana ${w.week} — ${w.title}</span><span class="week-sub">Capítulo ${w.chapter} · foco: pp. ${w.focusPages} · ${count}/5 etapas</span></span><span class="week-progress">${Math.round(count/5*100)}%　⌄</span></button><div class="topic-list"><div class="week-detail"><span>Capítulo completo: pp. ${w.chapterPages}</span><span>${finished?'✓ Semana concluída':'Em andamento'}</span></div><button class="topic-open" type="button" data-week="${w.week}">Ver plano de estudo da semana →</button></div></article>`}).join('');
}
function openWeek(n){const w=curriculum[n-1],s=getState(n);activeWeek=n;$('dialogWeek').textContent=`SEMANA ${n} · CAPÍTULO ${w.chapter}`;$('dialogTitle').textContent=w.title;$('dialogIntro').textContent=`Leitura do livro O Algebrista: foco nas páginas ${w.focusPages}. O capítulo completo ocupa as páginas ${w.chapterPages}. Siga o roteiro de seis dias.`;
 $('dialogPlan').innerHTML=w.days.map(d=>`<article class="plan-day"><strong>${d.day}</strong><p><b>Leitura:</b> ${d.reading}</p><p><b>Videoaula / revisão:</b> ${d.video}</p><p><b>Exercícios e correção:</b> ${d.practice}</p></article>`).join('');
 stages.forEach(k=>{$(k+'Check').checked=!!s[k]});if(typeof $('lessonDialog').showModal==='function')$('lessonDialog').showModal();else $('lessonDialog').setAttribute('open','');}
function saveProgress(){storageSet(KEY+'-progress',JSON.stringify(progress));render()}
function init(){if(!$('weeks'))return;
 $('weeks').addEventListener('click',e=>{const head=e.target.closest('.week-head');if(head){const card=head.closest('.week-card');card.classList.toggle('open');head.setAttribute('aria-expanded',card.classList.contains('open')?'true':'false');return}const b=e.target.closest('.topic-open');if(b)openWeek(Number(b.dataset.week))});
 stages.forEach(k=>$(k+'Check').addEventListener('change',e=>{if(activeWeek===null)return;const s=getState(activeWeek);s[k]=e.target.checked;progress[activeWeek]=s;saveProgress()}));
 $('weekFilter').addEventListener('change',render);$('menuButton').addEventListener('click',()=>$('mainNav').classList.toggle('show'));document.querySelectorAll('#mainNav a').forEach(a=>a.addEventListener('click',()=>$('mainNav').classList.remove('show')));
 function setupNotebook(id,button,status,key){$(id).value=storageGet(KEY+'-'+key,storageGet('matematica-construcao-v2-'+key,''));$(button).addEventListener('click',()=>{$(status).textContent=storageSet(KEY+'-'+key,$(id).value)?'Salvo neste dispositivo.':'Não foi possível salvar neste navegador.'})}
 setupNotebook('notes','saveNotes','notesStatus','notes');setupNotebook('errors','saveErrors','errorsStatus','errors');render();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
